      star(cx + R * 1.12, cy - R * 0.78, R * 0.07, 0.25 + 0.75 * tw(4), "#33D5FB"); star(cx - R * 1.08, cy + R * 0.55, R * 0.055, 0.25 + 0.75 * tw(1), "#2B47F6");
